#include "config.h"
#include <assert.h>
#include <bitcoin/feerate.c>
#include <common/setup.h>
#include <stdio.h>

/* AUTOGENERATED MOCKS START */
/* AUTOGENERATED MOCKS END */

/* What bitcoind charges at a minimum of perkvb sat/kvB. */
static u64 bitcoind_min_fee(u64 perkvb, u64 weight)
{
	u64 vsize = (weight + 3) / 4;
	return (perkvb * vsize + 999) / 1000;
}

static bool relays(u64 perkvb, u32 feerate, u64 weight)
{
	return (u64)feerate * weight / 1000 >= bitcoind_min_fee(perkvb, weight);
}

int main(int argc, const char *argv[])
{
	common_setup(argv[0]);

	assert(feerate_relay_floor(0) == FEERATE_FLOOR);
	assert(feerate_relay_floor(BITCOIND_MINRELAYTXFEE_PER_KW) == FEERATE_FLOOR);
	assert(feerate_relay_floor(UINT32_MAX) == UINT32_MAX);

	/* Floors as bitcoind reports them (sat/kvB), converted as we do:
	 * every one up to 20 sat/vB, then a sample up to FEERATE_CEILING.
	 * Small weights are the hard case. */
	for (u64 perkvb = 1; perkvb < 4000000; perkvb += perkvb < 20000 ? 1 : 997) {
		u32 floor = feerate_from_style(perkvb, FEERATE_PER_KBYTE);
		u32 rate = feerate_relay_floor(floor);

		/* Never much more than bitcoind's own floor. */
		assert(perkvb <= 1000
		       || (u64)rate * 4 <= perkvb + perkvb / 100 + 40);

		for (u64 weight = MINIMUM_TX_WEIGHT; weight < 800; weight++)
			assert(relays(perkvb, rate, weight));
		for (u64 weight = 800; weight < 400000; weight += 9973)
			assert(relays(perkvb, rate, weight));
	}

	common_shutdown();
	return 0;
}
